def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    opp_d = 0
    my_d = 0
    opp_c = 0
    my_c = 0
    cc = 0
    for pair in history:
        a, b = pair
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1
            if a == 'C':
                cc += 1
        else:
            opp_d += 1

    last_my, last_opp = history[-1]
    prev_my, prev_opp = history[-2]

    tail = history[-6:] if n >= 6 else history
    tail_opp_c = 0
    tail_opp_d = 0
    for pair in tail:
        if pair[1] == 'C':
            tail_opp_c += 1
        else:
            tail_opp_d += 1

    opp_rate = float(opp_c) / n

    if opp_d == 0:
        if n >= 90:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if opp_rate > 0.9 and n >= 20:
            return 'D'
        if tail_opp_d >= 5:
            return 'D'
        if tail_opp_d >= 3:
            if rng.random() < 0.75:
                return 'D'
        if tail_opp_d == 2:
            if rng.random() < 0.55:
                return 'D'
        if tail_opp_d == 1:
            if rng.random() < 0.35:
                return 'D'
        if last_my == 'D' and opp_rate > 0.6:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if n >= 92 and opp_rate > 0.75 and opp_d <= 4:
            if rng.random() < 0.6:
                return 'D'
        if tail_opp_d >= 4:
            return 'D'
        if tail_opp_d >= 2 and last_my == 'D' and opp_rate < 0.5:
            return 'D'
        if last_my == 'D':
            return 'C'
        if tail_opp_c >= 4:
            return 'C'
        if opp_rate > 0.55:
            return 'C'
        if n >= 30 and opp_rate <= 0.35:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'C'

    return 'C'
